p14e2.sql:
select nombre, duracion_dias
from excursion
where duracion_dias > 1;

p14e7.sql:
select nombre, apellido, tel
from huesped
where tel is null;

p14e9.sql:
select nombre, detalle
from excursion
where nombre like '%Jusenkyo%' or detalle like '%Jusenkyo%';

p14e10.sql:
select nombre, descripcion
from servicio
where nombre like '%erm%' or descripcion like '%erm%';

p14e11.sql:
select distinct condicion_iva
from cliente
order by condicion_iva;

p14e20.sql:
select nombre, apellido, upper(apellido) as apellido_mayus
from empleado
order by apellido;
